={
  "from": "Estimate Requests <websiteform@exclusive-ca.com>",
  "to": ["walterj@exclusive-ca.com", "aidans@exclusive-ca.com"],
  "reply_to": {{ JSON.stringify($json.body.email) }},
  "subject": {{ JSON.stringify('New Estimate: ' + $json.body.company + ' — ' + $json.body.projectType) }},
  "html": {{ JSON.stringify('<div style="font-family:Arial,sans-serif;color:#111;max-width:600px"><h2 style="color:#1d4ed8;margin-bottom:8px">New Estimate Request</h2><p style="color:#666;margin-top:0">Submitted via exclusive-ca.com</p><p><strong>' + $json.body.name + '</strong> from <strong>' + $json.body.company + '</strong> (' + $json.body.role + ') requested an estimate.</p><h3 style="border-bottom:1px solid #e5e7eb;padding-bottom:6px;margin-top:24px">Project Details</h3><table cellpadding="4" style="border-collapse:collapse"><tr><td style="color:#666;padding-right:16px">Project type</td><td><strong>' + $json.body.projectType + '</strong></td></tr><tr><td style="color:#666;padding-right:16px">Role</td><td><strong>' + $json.body.role + '</strong></td></tr><tr><td style="color:#666;padding-right:16px">Timeline</td><td><strong>' + $json.body.timeline + '</strong></td></tr><tr><td style="color:#666;padding-right:16px">Address</td><td><strong>' + $json.body.address + '</strong></td></tr></table><h3 style="border-bottom:1px solid #e5e7eb;padding-bottom:6px;margin-top:24px">Project Description</h3><p style="white-space:pre-wrap">' + $json.body.description + '</p><h3 style="border-bottom:1px solid #e5e7eb;padding-bottom:6px;margin-top:24px">Contact</h3><p>' + $json.body.name + '<br>' + $json.body.company + '<br>Phone: ' + $json.body.phone + '<br>Email: ' + $json.body.email + '</p><p style="color:#9ca3af;font-size:12px;margin-top:32px;border-top:1px solid #e5e7eb;padding-top:12px">Reply to this email to respond directly to the customer.</p></div>') }}
}
